const f = $('Cerrar plan').first().json;
let r = $input.first().json || {};
if (typeof r.data === 'string') {
  try { r = JSON.parse(r.data); } catch (e) { r = { ok: false, error: 'respuesta_no_json' }; }
}
const p = r.plan || r.data || r;
const opciones = Array.isArray(p.opciones) ? p.opciones : Array.isArray(p.options) ? p.options : [];
const estado = String(p.estado || '').toLowerCase();
const caido = String(f.resultado || '').toLowerCase().indexOf('cay') >= 0;
const idx = parseInt(f.opcion_ganadora, 10) - 1;
const op = opciones[idx];
let plan = '';
let lugar = '';
if (op) {
  plan = op.titulo || op.title || '';
  const paradas = Array.isArray(op.paradas) ? op.paradas : Array.isArray(op.stops) ? op.stops : Array.isArray(op.lugares) ? op.lugares : [];
  lugar = paradas.map((s) => (s.nombre || s.name || '[lugar]') + ' (' + (s.zona || s.zone || '[zona]') + ')').join(' → ');
}
const zona = 'America/Bogota';
const crudo = String(f.fecha_hora_encuentro || '').trim();
let dt = DateTime.fromFormat(crudo, 'yyyy-MM-dd HH:mm', { zone: zona });
if (!dt.isValid) dt = DateTime.fromISO(crudo, { zone: zona });
if (!dt.isValid) dt = DateTime.fromFormat(crudo, 'd/M/yyyy HH:mm', { zone: zona });
const ahora = DateTime.now().setZone(zona);
let accion = 'error';
let codigo = '';
let motivo = '';
if (r.ok !== true) { codigo = String(r.error || r.code || 'view_plan_fallido'); motivo = 'Cierre: no se pudo leer el plan (view=plan).'; }
else if (estado === 'caido') { codigo = 'plan_ya_caido'; motivo = 'Cierre: el plan ya estaba caído en el backend.'; }
else if (caido) { accion = 'caido'; }
else if (!(idx >= 0 && idx <= 2)) { codigo = 'opcion_invalida'; motivo = 'Cierre: falta la opción ganadora (1–3).'; }
else if (!op) { codigo = 'opcion_inexistente'; motivo = 'Cierre: la opción ganadora no existe en las opciones del motor.'; }
else if (!dt.isValid) { codigo = 'fecha_invalida'; motivo = 'Cierre: fecha_hora_encuentro no se pudo leer (usa 2026-10-31 19:00).'; }
else { accion = 'confirmar'; }
let tAviso = '';
if (dt.isValid) {
  let t = dt.minus({ hours: 2 });
  if (t < ahora) t = ahora.plus({ seconds: 5 });
  tAviso = t.toISO();
}
return [{ json: {
  accion, codigo, motivo: motivo ? motivo + ' No se envió nada al grupo. Usa «Pasar al mago» en la consola' : '',
  plan_id: f.plan_id,
  elegida: idx,
  causa_caida: f.causa_caida || 'otro',
  n_votos: p.n_votos !== undefined ? p.n_votos : '?',
  n_invitados: p.n_invitados !== undefined ? p.n_invitados : '?',
  plan, lugar,
  hora: dt.isValid ? dt.setLocale('es').toFormat("cccc d 'de' LLLL, h:mm a") : '',
  hora_encuentro: dt.isValid ? dt.toISO() : '',
  t_aviso_salida: tAviso,
  hora_salida: String(f.hora_salida || (op && op.hora_salida) || '').trim(),
  presupuesto: op ? String(op.presupuesto_aprox || '') : '',
  direccion: String(f.direccion || '').trim(),
} }];

