const a = $('Analizar cierre').first().json;
const t = $('Textos').first().json;
const valores = { plan: a.plan, lugar: a.lugar, hora: a.hora, direccion: a.direccion, salida_sugerida: a.hora_salida, hora_salida: a.hora_salida, presupuesto: a.presupuesto };
const faltan = { plan: '[plan]', lugar: '[lugar]', hora: '[hora]', direccion: '[dirección]', salida_sugerida: '[hora de salida]', hora_salida: '[hora de salida]', presupuesto: '[presupuesto]' };
const llenar = (plantilla) => {
  let s = String(plantilla || '');
  for (const k of Object.keys(valores)) s = s.split('{' + k + '}').join(valores[k] ? String(valores[k]) : faltan[k]);
  s = s.split('{dirección}').join(a.direccion ? a.direccion : '[dirección]');
  return s;
};
return [{ json: { texto_confirmado: llenar(t.plantilla_confirmado), texto_salida: llenar(t.plantilla_salida) } }];

const fila = $('Releer plan en tabla').first().json || {};
let r = $input.first().json || {};
if (typeof r.data === 'string') {
  try { r = JSON.parse(r.data); } catch (e) { r = { ok: false, error: 'respuesta_no_json' }; }
}
const p = r.plan || r.data || r;
const estadoBackend = String(p.estado || '').toLowerCase();
let accion = 'enviar';
let codigo = '';
if (String(fila.estado || '') === 'caido' || fila.salida_enviada) accion = 'parar';
else if (r.ok !== true) { accion = 'error'; codigo = String(r.error || r.code || 'view_plan_fallido'); }
else if (estadoBackend === 'caido') accion = 'parar';
return [{ json: { accion, codigo } }];
